LawfulContinuationCore.CoherentSection:
{ℓ : Level} {ℓe = ℓ′ : Level} {ℓf = W : Level} {S = n : Type ℓ}
(F : ContinuationFamily n) →
Type (ℓ-max (ℓ-max ℓ ℓ′) W)

KFlowWF.acc-invImage:
{ℓ ℓ' ℓ'' : Level} {A : Type ℓ} {B : Type ℓ'}
(_⊏_ : B → B → Type ℓ'') (μ : A → B) (x : A) →
Acc _⊏_ (μ x) → Acc (InvImage _⊏_ μ) x

KFlowWF.wf-invImage:
{ℓ ℓ' ℓ'' : Level} {A : Type ℓ} {B : Type ℓ'}
(_⊏_ : B → B → Type ℓ'') (μ : A → B) →
WellFounded _⊏_ → WellFounded (InvImage _⊏_ μ)
